const input = $input.first().json || {};
const workflowKey = String(input.workflow_key || '').trim();
const workflowVersion = String(input.workflow_version || 'unknown').trim();
const executionId = String(input.execution_id || '').trim();
const idempotencyKey = String(input.idempotency_key || '').trim();
const occurredAt = String(input.occurred_at || new Date().toISOString()).trim();
const ownerId = String(input.owner_id || '').trim();
const eventId = String(input.event_id || '').trim();

if (!/^[a-z0-9][a-z0-9-]{1,119}$/.test(workflowKey)) throw new Error('invalid_workflow_key');
if (!workflowVersion || workflowVersion.length > 80) throw new Error('invalid_workflow_version');
if (!executionId || executionId.length > 255) throw new Error('invalid_execution_id');
if (!idempotencyKey || idempotencyKey.length > 255) throw new Error('invalid_idempotency_key');
if (!Number.isFinite(Date.parse(occurredAt))) throw new Error('invalid_occurred_at');

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (ownerId && !uuid.test(ownerId)) throw new Error('invalid_owner_id');
if (eventId && !uuid.test(eventId)) throw new Error('invalid_event_id');

return [{json:{receipt:{
  workflow_key:workflowKey,
  workflow_version:workflowVersion,
  execution_id:executionId,
  status:'SUCCEEDED',
  idempotency_key:idempotencyKey,
  occurred_at:new Date(occurredAt).toISOString(),
  owner_id:ownerId || null,
  event_id:eventId || null,
  error_code:null,
  error_message:null
}}}];

const crypto = require('crypto');
const receipt = $json.receipt;
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const url = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!url) throw new Error('automation_control_url_not_configured');
const body = JSON.stringify(receipt);
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + body, 'utf8')
  .digest('hex');
return [{json:{
  receipt_url:url,
  receipt_body:body,
  receipt_timestamp:timestamp,
  receipt_signature:signature
}}];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode || 0);
if (statusCode < 200 || statusCode >= 300) {
  throw new Error('automation_success_receipt_failed_http_' + statusCode);
}
const body = response.body || {};
if (body.accepted !== true || body.status !== 'SUCCEEDED') {
  throw new Error('automation_success_receipt_not_accepted');
}
return [{json:{
  recorded:true,
  workflow_key:body.workflow_key,
  execution_id:body.execution_id,
  duplicate_owner_receipts:Number(body.duplicate_owner_receipts || 0)
}}];
